const $=s=>document.querySelector(s), audio=$('#audio');
const photos=['photo-1472396961693-142e6e269027','photo-1441974231531-c6227db76b6e','photo-1519681393784-d120267933ba','photo-1518837695005-2083093ee35b'];
const image=(i,w=600)=>`room-${i%4}.jpg`;
function coverSource(value,fallback=image(0)){if(!value)return fallback;try{const u=new URL(value),h=u.hostname.toLowerCase(),allowed=['avatars.yandex.net','avatars.mds.yandex.net','avatars.mds.yandex.ru','i.scdn.co','mosaic.scdn.co'].includes(h)||h.endsWith('.sndcdn.com');if(backend&&allowed&&u.protocol==='https:'&&!u.username&&!u.password&&![...u.searchParams.keys()].some(k=>/token|oauth|cookie|authorization/i.test(k)))return '/api/artwork?url='+encodeURIComponent(u.href)}catch{}return value}
const rooms=[['Тихий вечер','Мягкий эмбиент · выдохнуть',0],['В потоке','Без слов · сосредоточиться',1],['После полуночи','Глубокий звук · остаться с собой',2],['Ближе к морю','Воздушные текстуры · замедлиться',3]];
let tracks=[],current=null,page='home',queue=[],likes=new Set(JSON.parse(localStorage.getItem('soulroom.likes')||'[]')),shuffle=false,repeat=false,backend=false,sourceFilter='all',searchItems=[],searchTimer,searchVersion=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const artist=t=>(t.artists||['Неизвестный исполнитель']).join(', '),fmt=n=>`${Math.floor((n||0)/60)}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
async function api(path,options){const r=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options?.headers},signal:options?.signal||AbortSignal.timeout(25000)});const j=await r.json();if(!r.ok)throw Error(j.error?.message||'Источник не ответил. Попробуй ещё раз.');return j}
function row(t,i){return `<div class="track-row" data-track="${esc(t.id)}" role="button" tabindex="0"><span class="number">${current?.id===t.id?'♫':String(i+1).padStart(2,'0')}</span><img class="art" src="${esc(coverSource(t.cover,image(i)))}" alt="" loading="lazy"><div class="track-info"><strong>${esc(t.title)}</strong><small>${esc(artist(t))}</small></div><span class="source">${({demo:'SESSION',local:'ФАЙЛ',soundcloud:'SOUNDCLOUD',yandex:'ЯНДЕКС',spotify:'SPOTIFY'})[t.source]||esc(t.source)}</span><time>${fmt(t.duration)}</time><button data-like="${esc(t.id)}" aria-label="В любимое" class="${likes.has(t.id)?'is-on':''}">${likes.has(t.id)?'♥':'♡'}</button></div>`}
function heading(title,sub){return `<div class="greeting"><div><div class="eyebrow">ТВОЁ ЛИЧНОЕ ПРОСТРАНСТВО</div><h1>${title}</h1></div><p>${sub}</p></div>`}
function home(){return heading('Побудь <em>в музыке.</em>','Всё, что нужно, чтобы услышать себя.')+`<section class="hero"><div class="hero-content"><div class="hero-label"><i class="dot green"></i> ТВОЯ КОМНАТА ЗВУКА</div><h2>Мир тише.<br>Музыка ближе.</h2><p>Оставь суету за дверью.<br>Здесь только ты и то, что звучит.</p><button class="primary" data-room="0">▶ <span>Включить тихий вечер</span></button></div><span class="hero-caption">ВДОХНОВЕНИЕ ПРИРОДОЙ / 001</span></section><div class="section-head"><h2>Как ты сейчас?</h2><span>МУЗЫКА ПОД ТВОЙ РИТМ</span></div><section class="rooms">${rooms.map((r,i)=>`<button class="room" data-room="${i}"><div class="cover"><img src="${image(r[2])}" alt="${r[0]}" loading="lazy"><span class="room-num">0${i+1} / ROOM</span><span class="room-play">▶</span></div><strong>${r[0]}</strong><small>${r[1]}</small></button>`).join('')}</section><section class="lower"><div><div class="section-head"><h2>Останутся с тобой</h2><button class="text-button" data-page="library">Вся коллекция ↗</button></div>${tracks.slice(-4).map(row).join('')}</div><div><div class="section-head"><h2>Меньше шума</h2><span>БОЛЬШЕ ТЕБЯ</span></div><div class="note"><span>♪</span><h3>Музыка не должна<br>требовать внимания.</h3><p>Добавь свои файлы или подключи источник.<br>Всё любимое останется в одной комнате.</p><button data-page="connections">Настроить пространство ↗</button></div></div></section>`}
function render(){document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent=({home:'СЛУШАТЬ',search:'ПОИСК',library:'КОЛЛЕКЦИЯ',favorites:'ЛЮБИМОЕ',connections:'ИСТОЧНИКИ'})[page];let html='';if(page==='home')html=home();if(page==='library'||page==='favorites'){const items=page==='favorites'?tracks.filter(t=>likes.has(t.id)):tracks;html=heading(page==='favorites'?'Любимое.':'Твоя коллекция.',`${items.length} треков · одно пространство`)+`<div class="section-head"><span>ТВОЯ МУЗЫКА</span><button class="primary" data-import>＋ Добавить файлы</button></div>`+(items.length?items.map(row).join(''):'<div class="empty"><h2>Здесь будет любимое</h2><p>Нажми на сердце рядом с треком, чтобы сохранить его.</p><button class="primary" data-page="home">Найти свой звук</button></div>')}
if(page==='search')html=heading('Что хочется услышать?','Поиск по твоим файлам и доступным каталогам')+`<input class="search-box" id="query" placeholder="Трек, исполнитель или альбом…" aria-label="Поиск музыки"><div class="filters">${[['all','Всё'],['local','Мои файлы'],['soundcloud','SoundCloud'],['yandex','Яндекс'],['spotify','Spotify']].map(([k,v])=>`<button data-filter="${k}" class="${sourceFilter===k?'selected':''}">${v}</button>`).join('')}</div><p id="searchHint">${backend?'Введи название — проверим подключённые источники.':'Веб-версия ищет в коллекции. Каталоги доступны в локальном приложении.'}</p><div id="results"></div>`;
if(page==='connections')html=heading('Твоё пространство.','Настрой один раз. Дальше — только музыка.')+`<div class="settings-card"><h3>Своя музыка <span class="is-on">●</span></h3><p>MP3, FLAC, WAV, OGG и M4A — поддержка зависит от браузера. Файлы остаются на этом устройстве и сохраняются в локальной коллекции.</p><button class="primary" data-import>Добавить файлы</button></div><div class="settings-card"><h3>Яндекс.Музыка</h3><p>${backend?'Подключи личный OAuth-токен для поиска и прослушивания.':'Подключение доступно в локальной версии soulroom. Запусти start.cmd из папки приложения.'}</p>${backend?'<form id="yandexForm"><input id="ymToken" type="password" autocomplete="off" placeholder="OAuth-токен" aria-label="OAuth-токен Яндекса"><button class="primary">Подключить Яндекс</button></form>':''}</div><div class="settings-card"><h3>SoundCloud</h3><p>Поиск и воспроизведение доступны через сервер приложения. Доступность конкретного трека зависит от сервиса и сети.</p><button class="primary" id="checkSources">Проверить источники</button><p id="sourceStatus"></p></div><div class="settings-card"><h3>Spotify</h3><p>Источник каталога. Полное воспроизведение Spotify в этом плеере не поддерживается.</p>${backend?'<form id="spotifyForm"><input id="spId" placeholder="Client ID" aria-label="Spotify Client ID"><input id="spSecret" type="password" placeholder="Client Secret" aria-label="Spotify Client Secret"><button class="primary">Подключить каталог</button></form>':''}</div><div class="settings-card"><h3>Облик</h3><p>Спокойный тёмный или светлый дневной.</p><button class="primary" id="themeSetting">Сменить тему</button></div>`;
$('#view').innerHTML=html;if(page==='search')$('#query').focus();renderQueue()}
function go(p){page=p;render();window.scrollTo(0,0)}
function renderQueue(){$('#queueList').innerHTML=queue.map(row).join('')}
function find(id){return tracks.find(t=>t.id===id)||searchItems.find(t=>t.id===id)||queue.find(t=>t.id===id)}
let favoritesWrites=Promise.resolve(),favoritesInitialized=false;
function backupFavorites(){
 if(!backend||!favoritesInitialized)return;
 const body=JSON.stringify({ids:[...likes].filter(id=>!id.startsWith('demo:')),tracks:tracks.filter(t=>likes.has(t.id)&&!['demo','local'].includes(t.source))});
 favoritesWrites=favoritesWrites.catch(()=>{}).then(()=>api('player-favorites',{method:'PUT',body})).catch(()=>{});
}
document.addEventListener('backend-ready',async()=>{
 try{
   const {snapshot}=await api('player-favorites');
   if(snapshot && localStorage.getItem('soulroom.likes')===null){
     likes=new Set(snapshot.ids.filter(id=>!id.startsWith('demo:')));
     localStorage.setItem('soulroom.likes',JSON.stringify([...likes]));
   }
   for(const t of snapshot?.tracks||[])if(t.source!=='demo'&&likes.has(t.id)&&!tracks.some(item=>item.id===t.id))tracks.push(t);
   if(snapshot){saveRemote();if(page==='favorites'||page==='library')render()}
   favoritesInitialized=true;backupFavorites();
 }catch{}
});
function toggleLike(id){if(likes.has(id))likes.delete(id);else likes.add(id);localStorage.setItem('soulroom.likes',JSON.stringify([...likes]));const t=find(id);if(t&&!tracks.some(x=>x.id===id))tracks.push(t);saveRemote();backupFavorites();sync();if(page==='favorites'||page==='library'||page==='home')render();else renderQueue()}
function sync(){$('#play').textContent=audio.paused?'▶':'Ⅱ';$('#play').setAttribute('aria-label',audio.paused?'Воспроизвести':'Приостановить');$('#like').textContent=likes.has(current?.id)?'♥':'♡';$('#like').classList.toggle('is-on',likes.has(current?.id));if(current){$('#nowTitle').textContent=current.title;$('#nowArtist').textContent=artist(current);$('#miniArt').style.backgroundImage=`url("${coverSource(current.cover,image(0))}")`}$('#shuffle').classList.toggle('is-on',shuffle);$('#repeat').classList.toggle('is-on',repeat)}
function trackStreamUrl(t){const base='/api/stream/'+encodeURIComponent(t.source)+'/'+encodeURIComponent(t.sourceId||t.id.split(':').slice(1).join(':'));return base+(t.source==='soundcloud'&&audio.canPlayType?.('audio/mp4; codecs="mp4a.40.2"')?'?aac=1':'')}
async function play(t){if(!t)return;if(t.playable===false){toast(t.source==='spotify'?'Для этого трека нужно найти версию в Яндексе или SoundCloud.':'Этот трек недоступен для воспроизведения.');return}current=t;audio.src=t.source==='local'&&t.url?t.url:trackStreamUrl(t);sync();try{await audio.play();if(backend&&t.source!=='demo'&&t.source!=='local')api('history',{method:'POST',body:JSON.stringify({track:t,playedSeconds:0})}).catch(()=>{});sync();renderQueue()}catch{toast('Не удалось включить трек. Проверь формат файла или доступность источника.');sync()}}
function step(dir){if(!queue.length)return;let i=queue.findIndex(t=>t.id===current?.id);if(shuffle&&queue.length>1){let next;do{next=Math.floor(Math.random()*queue.length)}while(next===i);i=next}else i=(i+dir+queue.length)%queue.length;play(queue[i])}
$('#play').onclick=()=>{if(!current)return play(queue[0]);if(audio.paused)audio.play().catch(()=>toast('Не удалось продолжить воспроизведение.'));else audio.pause()};$('#prev').onclick=()=>audio.currentTime>3?audio.currentTime=0:step(-1);$('#next').onclick=()=>step(1);$('#shuffle').onclick=()=>{shuffle=!shuffle;sync()};$('#repeat').onclick=()=>{repeat=!repeat;sync()};$('#like').onclick=()=>current&&toggleLike(current.id);$('#volume').oninput=e=>{audio.volume=+e.target.value;audio.muted=false};audio.volume=.7;$('#mute').onclick=()=>{audio.muted=!audio.muted;$('#mute').classList.toggle('is-on',audio.muted)};$('#seek').oninput=e=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*e.target.value/1000};audio.ontimeupdate=()=>{$('#elapsed').textContent=fmt(audio.currentTime);$('#duration').textContent=fmt(audio.duration);$('#seek').value=audio.duration?audio.currentTime/audio.duration*1000:0};audio.onended=()=>repeat?(audio.currentTime=0,audio.play().catch(()=>{})):step(1);audio.onplay=audio.onpause=sync;audio.onerror=()=>{toast('Поток недоступен. Попробуй другой трек или проверь источник.');sync()};$('#queueToggle').onclick=()=>$('#queue').classList.toggle('hidden');$('#closeQueue').onclick=()=>$('#queue').classList.add('hidden');function theme(){document.body.classList.toggle('light');localStorage.setItem('soulroom.theme',document.body.classList.contains('light')?'light':'dark')}$('#theme').onclick=theme;if(localStorage.getItem('soulroom.theme')==='light')document.body.classList.add('light');
const dbPromise=new Promise(resolve=>{try{if(!window.indexedDB){resolve(null);return}const r=indexedDB.open('soulroom-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=r.onblocked=()=>resolve(null)}catch{resolve(null)}});
async function addFiles(files){let count=0;for(const file of files){if(!file.type.startsWith('audio/')&&!/\.(mp3|flac|wav|ogg|m4a)$/i.test(file.name))continue;const id=`local:${file.name}:${file.size}:${file.lastModified}`;if(tracks.some(t=>t.id===id))continue;const t={id,title:file.name.replace(/\.[^.]+$/,''),artists:['Моя музыка'],source:'local',cover:image(count),duration:0,playable:true,url:URL.createObjectURL(file)};tracks.push(t);queue.push(t);const db=await dbPromise;if(db){const tx=db.transaction('files','readwrite');tx.objectStore('files').put({id,file,title:t.title,cover:t.cover});tx.onerror=()=>toast('Файл добавлен на этот сеанс: хранилище браузера заполнено.')}count++}toast(count?`Добавлено треков: ${count}`:'Новых аудиофайлов не найдено.');go('library')}
$('#import').onclick=()=>$('#files').click();$('#files').onchange=e=>{addFiles(e.target.files);e.target.value=''};document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length)addFiles(e.dataTransfer.files)});
function saveRemote(){localStorage.setItem('soulroom.saved',JSON.stringify(tracks.filter(t=>!['demo','local'].includes(t.source))))}
let searchController;
async function search(input,sourcesOverride){
  const version=++searchVersion, query=input.trim();
  searchController?.abort();
  const controller=searchController=new AbortController();
  const filter=sourceFilter, sources=filter==='local'?[]:sourcesOverride?sourcesOverride.split(','):filter==='all'?enabledSources:[filter];
  const groups=new Map(),failed=[],local=tracks.filter(t=>(filter==='all'||t.source===filter)&&[t.title,artist(t),t.album].join(' ').toLowerCase().includes(query.toLowerCase()));
  function show(pending){
    if(version!==searchVersion||page!=='search'||!$('#results'))return;
    const items=query?[...local,...sources.flatMap(source=>groups.get(source)||[])]:[];
    searchItems=[...new Map(items.map(t=>[t.id,t])).values()];
    $('#results').innerHTML=searchItems.map(row).join('')||(!pending&&query?'<div class="empty">Треки не найдены</div>':'');
    $('#searchHint').textContent=!query?'Введи название трека или исполнителя':(searchItems.length?'Найдено: '+searchItems.length:'')+(pending?' · Ищем…':'')+(failed.length?' · Не ответили: '+failed.map(s=>serviceNames[s]).join(', '):'');
  }
  let pending=backend&&query?sources.length:0;
  show(pending);
  if(!pending)return;
  await Promise.all(sources.map(async source=>{
    try{
      const data=await api('search?'+new URLSearchParams({q:query,sources:source,limit:'15'}),{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(16000)])});
      const group=data.groups?.find(g=>g.source===source);
      groups.set(source,group?.items||[]);
      if(group?.error)failed.push(source);
    }catch{failed.push(source)}finally{show(--pending)}
  }));
}
document.addEventListener('input',e=>{if(e.target.id==='query'){clearTimeout(searchTimer);searchVersion++;searchTimer=setTimeout(()=>search(e.target.value),260)}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-track]');if(!b)return;if(b.dataset.page)go(b.dataset.page);if(b.hasAttribute('data-import'))$('#files').click();if(b.dataset.like){toggleLike(b.dataset.like);return}if(b.dataset.track){const t=find(b.dataset.track);queue=page==='search'?[...searchItems]:page==='favorites'?tracks.filter(t=>likes.has(t.id)):[...tracks];play(t)}if(b.dataset.filter){sourceFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));search($('#query').value)}if(b.id==='themeSetting')theme();if(b.id==='checkSources'){if(!backend){toast('Открой локальное приложение через start.cmd для подключения каталогов.');return}$('#sourceStatus').textContent='Проверяем…';try{const d=await api('status');$('#sourceStatus').textContent=Object.entries(d.sources||{}).map(([k,v])=>`${k}: ${v.connected?'подключён':'не подключён'}`).join(' · ')}catch(e){$('#sourceStatus').textContent=e.message}}});
document.addEventListener('submit',async e=>{e.preventDefault();let body;if(e.target.id==='yandexForm'){const token=$('#ymToken').value.trim();if(!token)return toast('Вставь OAuth-токен.');body={yandex:{token}}}if(e.target.id==='spotifyForm')body={spotify:{clientId:$('#spId').value.trim(),clientSecret:$('#spSecret').value.trim()}};if(body)try{await api('settings',{method:'PUT',body:JSON.stringify(body)});e.target.reset();toast('Настройки сохранены. Проверь подключение источников.')}catch(e){toast(e.message)}});
document.addEventListener('keydown',e=>{if(e.defaultPrevented)return;if(/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)||e.target.isContentEditable)return;if(e.key===' '){e.preventDefault();$('#play').click()}if(e.key==='/'){e.preventDefault();go('search')}if(e.key==='Escape')$('#queue').classList.add('hidden');if(e.key==='Enter'&&e.target.dataset.track)e.target.click()});
async function init(){try{tracks.push(...JSON.parse(localStorage.getItem('soulroom.saved')||'[]').filter(t=>t?.source!=='demo'))}catch{}const db=await dbPromise;if(db){const r=db.transaction('files').objectStore('files').getAll();r.onsuccess=()=>{for(const x of r.result)tracks.push({id:x.id,title:x.title,artists:['Моя музыка'],source:'local',cover:x.cover,playable:true,url:URL.createObjectURL(x.file)});queue=[...tracks];render()}}render();try{await api('health');backend=true;document.dispatchEvent(new Event('backend-ready'));$('#mode').textContent='Сервер подключён'}catch{}if(page==='connections'||page==='search')render()};init();





